select test.expect_error('select test.call()','finalization_lease_changed');
select test.reset();
select test.expect_error('select test.call(''{"owner":"40000000-0000-4000-8000-000000000009"}'')','finalization_lease_changed');
select test.reset();
update private.email_exact_message_recovery_applications set actor_user_id='20000000-0000-4000-8000-000000000009' where provider_message_id='message-2';
select test.expect_error('select test.call()','finalization_evidence_mismatch');
select test.reset();
update private.email_exact_message_recovery_applications set status='attachment_pending' where provider_message_id='message-4';
select test.expect_error('select test.call()','finalization_evidence_mismatch');
select test.reset();
