select test.reset();
select test.expect_error('select test.call(''{"email":"unproven@example.test"}'')','finalization_target_identity_mismatch');

-- Force a failure after the canonical link write; both updates and all tokens
-- must roll back, while an outer caller's guard context must survive unchanged.
create function test.fail_thread_update() returns trigger language plpgsql as $$ begin raise exception 'injected_thread_failure'; end $$;
create trigger z_test_fail before update on public.email_threads for each row execute function test.fail_thread_update();
select set_config('ops.email_thread_reassignment_mode','outer-context',false);
select test.expect_error('select test.call()','injected_thread_failure');
select test.assert((select to_jsonb(l)=c.value->'link_snapshot' from public.opportunity_email_threads l cross join test.config c),'partial failure link rollback');
select test.assert((select count(*)=0 from private.email_thread_recovery_finalizations),'partial failure receipt rollback');
select test.assert((select count(*)=0 from private.opportunity_child_reparent_tokens),'failure token cleanup');
select test.assert(current_setting('ops.email_thread_reassignment_mode')='outer-context','failure outer context preserved');
drop trigger z_test_fail on public.email_threads;
select test.assert((test.call()->>'already_finalized')::boolean=false,'retry after rollback succeeds');
select test.assert(current_setting('ops.email_thread_reassignment_mode')='outer-context','success outer context preserved');
select test.assert(not has_function_privilege('authenticated','public.finalize_exact_email_thread_recovery_guarded(uuid,uuid,uuid,uuid,text,uuid,uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb)','execute'),'authenticated cannot execute');
select test.assert(not has_table_privilege('service_role','private.email_thread_recovery_finalizations','update'),'service cannot edit receipt');
select test.assert(not has_function_privilege('anon','public.finalize_exact_email_thread_recovery_guarded(uuid,uuid,uuid,uuid,text,uuid,uuid,text,text,jsonb,jsonb,jsonb,jsonb,jsonb)','execute'),'anon cannot execute');
select test.assert((select relrowsecurity from pg_class where oid='private.email_thread_recovery_finalizations'::regclass),'private ledger RLS enabled');

-- An expiry occurring inside an otherwise successful update must roll back.
select test.reset();
create function test.expire_lease() returns trigger language plpgsql as $$ begin update private.email_provider_mailbox_sync_leases set expires_at=clock_timestamp()-interval '1 second'; return new; end $$;
create trigger z_test_expire after update on public.email_threads for each row execute function test.expire_lease();
select test.expect_error('select test.call()','finalization_lease_changed');
select test.assert((select to_jsonb(l)=c.value->'link_snapshot' from public.opportunity_email_threads l cross join test.config c),'expired lease rolls back link');
select test.assert((select count(*)=0 from private.email_thread_recovery_finalizations),'expired lease creates no receipt');
drop trigger z_test_expire on public.email_threads;
select 'EXACT_THREAD_FINALIZATION_CONTRACTS_PASSED' as proof;
